from common import *
import traceback,statistics
def run_stage(name,args):
 harness('check');progress=read(PROGRESS);progress['pipeline_stage']=name;write(PROGRESS,progress)
 with (TMP/f'pipeline-{name}.log').open('w') as log:
  r=subprocess.run([sys.executable,'-B','-u',*args],cwd=ROOT,stdout=log,stderr=subprocess.STDOUT)
 if r.returncode:raise RuntimeError(f'{name} exited {r.returncode}; inspect log and ledger before retry')
 print('completed',name,flush=True)
def main():
 save_source(__file__)
 assert not any(j['status']=='running' for j in read(PROGRESS)['jobs'])
 for variant in VARIANTS:
  state=read(PROGRESS);status=state['scientific_candidates'][variant]['status']
  if status=='completed':continue
  done=sum(j['variant']==variant and j['status']=='succeeded' for j in state['jobs'])
  durations=[j['finished_at']-j['started_at'] for j in state['jobs'] if j['status']=='succeeded']
  estimate=max(660,statistics.median(durations)) if durations else 660
  remain=read(STATE)['deadline']-time.time()
  reserve={'remaining_seconds':remain,'outstanding_fits':5-done,'fit_seconds_estimate':estimate,'evaluation_reserve_seconds':1800,'closeout_reserve_seconds':2700,'start_allowed':remain>=(5-done)*estimate+4500}
  write(BASE/'docs'/f'budget-before-{variant}.json',reserve)
  if not reserve['start_allowed']:
   state['status']='budget_stop_pending_closeout';write(PROGRESS,state);return
  if status in ['planned','running']:run_stage('train-'+variant,[str(TMP/'train_group.py'),variant])
  for year in range(2020,2027):
   p=BASE/'docs'/f'inference-{variant}-{year}.json'
   if p.exists():
    for item in read(p)['predictions']:check(item['prediction_part'])
    continue
   run_stage(f'infer-{variant}-{year}',[str(TMP/'infer.py'),variant,str(year)])
  if read(PROGRESS)['scientific_candidates'][variant]['status']!='evaluated_awaiting_registration':
   run_stage('evaluate-'+variant,[str(TMP/'evaluate.py'),variant])
  run_stage('publish-'+variant,[str(TMP/'publish.py')])
 state=read(PROGRESS);state.update(status='evaluation_complete_awaiting_review',pipeline_finished_at=time.time());write(PROGRESS,state)
 print('All4 candidates evaluated and registered; final scientific review/native result/cleanup remain.',flush=True)
if __name__=='__main__':
 try:main()
 except BaseException as exc:
  p=BASE/'docs'/f'pipeline-failure-{int(time.time())}.json';write(p,{'error':repr(exc),'traceback':traceback.format_exc(),'stage':read(PROGRESS).get('pipeline_stage'),'at':time.time()})
  print('pipeline stopped',repr(exc),flush=True);raise
